solution.Shelf.java:
import java.util.*;
import java.util.stream.*;

class Shelf {
    static List<String> titlesBy(List<Book> books, String author) {
        return books.stream()
            .filter(b -> b.author().equals(author))
            .sorted(Comparator.comparingInt(Book::year).thenComparing(Book::title))
            .map(Book::title)
            .toList();
    }

    static Map<String, Double> averagePagesByGenre(List<Book> books) {
        return books.stream()
            .flatMap(b -> b.genres().stream().map(g -> Map.entry(g, b.pages())))
            .collect(Collectors.groupingBy(Map.Entry::getKey, TreeMap::new, Collectors.averagingInt(Map.Entry::getValue)));
    }

    static Map<Integer, Long> countByDecade(List<Book> books) {
        return books.stream().collect(Collectors.groupingBy(b -> b.year() / 10 * 10, TreeMap::new, Collectors.counting()));
    }

    static List<String> genresByPopularity(List<Book> books) {
        Map<String, Long> counts = books.stream()
            .flatMap(b -> b.genres().stream().distinct())
            .collect(Collectors.groupingBy(g -> g, Collectors.counting()));
        Comparator<Map.Entry<String, Long>> mostFirst = (a, b) -> Long.compare(b.getValue(), a.getValue());
        return counts.entrySet().stream()
            .sorted(mostFirst.thenComparing(Map.Entry::getKey))
            .map(Map.Entry::getKey)
            .toList();
    }

    static Optional<Book> longestBefore(List<Book> books, int year) {
        return books.stream().filter(b -> b.year() < year).max(Comparator.comparingInt(Book::pages));
    }

    static String authorsLine(List<Book> books) {
        return books.stream().map(Book::author).distinct().sorted().collect(Collectors.joining("; "));
    }
}

unitTests:
List<Book> books = List.of(
    new Book("Dune", "Herbert", 1965, 412, List.of("sf", "classic")),
    new Book("Children of Dune", "Herbert", 1976, 444, List.of("sf")),
    new Book("Dune Messiah", "Herbert", 1969, 256, List.of("sf")),
    new Book("Emma", "Austen", 1815, 474, List.of("classic", "romance")),
    new Book("Kindred", "Butler", 1979, 264, List.of("sf", "classic")),
    new Book("Persuasion", "Austen", 1817, 249, List.of("romance")));

test("titles by an author", () -> {
    checkEq(Shelf.titlesBy(books, "Herbert"), List.of("Dune", "Dune Messiah", "Children of Dune"));
    checkEq(Shelf.titlesBy(books, "Nobody"), List.of());
});

test("averages and decades", () -> {
    Map<String, Double> avg = Shelf.averagePagesByGenre(books);
    checkEq(new ArrayList<>(avg.keySet()), List.of("classic", "romance", "sf"));
    checkNear(avg.get("sf"), (412 + 444 + 256 + 264) / 4.0);
    checkNear(avg.get("romance"), (474 + 249) / 2.0);
    checkEq(Shelf.countByDecade(books), new TreeMap<>(Map.of(1810, 2L, 1960, 2L, 1970, 2L)));
});

test("popular genres", () -> {
    checkEq(Shelf.genresByPopularity(books), List.of("sf", "classic", "romance"));
});

test("optional results and joining", () -> {
    checkEq(Shelf.longestBefore(books, 1900).map(Book::title).orElse("-"), "Emma");
    checkEq(Shelf.longestBefore(books, 1800).isPresent(), false);
    checkEq(Shelf.authorsLine(books), "Austen; Butler; Herbert");
    checkEq(Shelf.authorsLine(List.of()), "");
});

